BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "TB_CIDADE" (
	"nome_cidade"	TEXT,
	PRIMARY KEY("nome_cidade")
);
CREATE TABLE IF NOT EXISTS "TB_COPA" (
	"ano"	INTEGER,
	"pais_sede"	TEXT,
	"campeao"	TEXT,
	"vice_campeao"	TEXT,
	"terceiro"	TEXT,
	"quarto"	TEXT,
	"gols_marcados"	INTEGER,
	"times_qualificados"	INTEGER,
	"partidas_jogadas"	INTEGER,
	"publico_total"	INTEGER,
	PRIMARY KEY("ano")
);
CREATE TABLE IF NOT EXISTS "TB_ESTADIO" (
	"nome_estadio"	TEXT,
	"nome_cidade"	TEXT,
	PRIMARY KEY("nome_estadio"),
	FOREIGN KEY("nome_cidade") REFERENCES "TB_CIDADE"("nome_cidade")
);
CREATE TABLE IF NOT EXISTS "TB_PARTIDA" (
	"id_partida"	INTEGER,
	"ano"	INTEGER,
	"data_hora"	TEXT,
	"fase"	TEXT,
	"nome_estadio"	TEXT,
	"sigla_mandante"	TEXT,
	"sigla_visitante"	TEXT,
	"gols_mandante"	INTEGER,
	"gols_visitante"	INTEGER,
	"publico"	INTEGER,
	"condicao_vitoria"	TEXT,
	PRIMARY KEY("id_partida"),
	FOREIGN KEY("ano") REFERENCES "TB_COPA"("ano"),
	FOREIGN KEY("nome_estadio") REFERENCES "TB_ESTADIO"("nome_estadio"),
	FOREIGN KEY("sigla_mandante") REFERENCES "TB_SELECAO"("sigla"),
	FOREIGN KEY("sigla_visitante") REFERENCES "TB_SELECAO"("sigla")
);
CREATE TABLE IF NOT EXISTS "TB_PARTIDA_JOGADOR" (
	"id_partida"	INTEGER,
	"sigla_selecao"	TEXT,
	"nome_jogador"	TEXT,
	"nome_tecnico"	TEXT,
	"numero_camisa"	INTEGER,
	"posicao"	TEXT,
	"titular"	TEXT,
	PRIMARY KEY("id_partida","sigla_selecao","nome_jogador"),
	FOREIGN KEY("id_partida") REFERENCES "TB_PARTIDA"("id_partida"),
	FOREIGN KEY("nome_tecnico") REFERENCES "TB_TECNICO"("nome_tecnico"),
	FOREIGN KEY("sigla_selecao") REFERENCES "TB_SELECAO"("sigla")
);
CREATE TABLE IF NOT EXISTS "TB_SELECAO" (
	"sigla"	TEXT,
	"nome_selecao"	TEXT NOT NULL,
	PRIMARY KEY("sigla")
);
CREATE TABLE IF NOT EXISTS "TB_TECNICO" (
	"nome_tecnico"	TEXT,
	PRIMARY KEY("nome_tecnico")
);
COMMIT;
